/// <summary>
/// CB705 Context class will contain instance for skip posting context
/// </summary>
public class METSkipPostingContext_BEC implements System.IDisposable
{
    static METSkipPostingContext_BEC instance;

    public boolean isCalledFromRebateBatch;


}

Method.Source:
public static METSkipPostingContext_BEC construct()
{
    return new METSkipPostingContext_BEC();
}

protected void new()
{
    if (instance)
    {
        throw Error("@MET:InstanceNotFound");
    }
    instance = this;
}

static public METSkipPostingContext_BEC current()
{
    return instance;
}
